// 工程机器人控制代码（由 PIE-Block Flutter 配置器自动生成）
#include "main.h"
#include <stdlib.h>

uint8_t Channal = 36;
uint16_t maxSpeed = 5000;
uint16_t ultraSpeed = 5000;
uint16_t deadBandOfLeft = 100;
uint16_t deadBandOfRight = 100;

#define COMM_HEADER_1 0xAB
#define COMM_HEADER_2 0xBC
#define COMM_END_1 0xCD
#define COMM_END_2 0xDE
#define Init_Order 0xAA
#define Duty_Change_Order 0xBB
#define Freq_Change_Order 0xCC
#define Dir_Change_Order 0xDD
#define EXPANSION_FRAME_GAP_MS 5

uint8_t valueOfKey[3][4];
int valueOfRoker[2][2];
int dutyOfMotor[8];
uint8_t control_frame_pack[21];

static void remoteControlInitWithTimeout(void)
{
    uint8_t retry;
    for (retry = 0; retry < 20; retry++) {
        if (NRF24L01_Init()) { Ms_Delay(200); return; }
        Ms_Delay(10);
    }
}

static void Uart1TxQuery(uint8_t dat)
{
    uint8_t uart1InterruptEnabled = ES;

    ES = 0;
    TI = 0;
    SBUF = dat;
    while (!TI) ;
    TI = 0;
    ES = uart1InterruptEnabled;
}

#define LED_PORT GPIO_P3
#define LED1_PIN GPIO_Pin_5
#define LED2_PIN GPIO_Pin_6
#define LED3_PIN GPIO_Pin_7
#define BUZZER_CH PWMA_CH4N_P33
static void LedShow(uint8_t show)
{
    GPIO_Write_Bit(LED_PORT, LED1_PIN, (show & 0x01) ? 0 : 1);
    GPIO_Write_Bit(LED_PORT, LED2_PIN, (show & 0x02) ? 0 : 1);
    GPIO_Write_Bit(LED_PORT, LED3_PIN, (show & 0x04) ? 0 : 1);
}
static void StepBegin(uint8_t step) { LedShow(step & 0x07); }
static void Beep(uint16_t freq, uint16_t ms)
{
    PWM_SET_Frequency(BUZZER_CH, freq, 5000);
    Ms_Delay(ms);
    PWM_SET_Frequency(BUZZER_CH, freq, 0);
}
static void StepDone(uint8_t step) { Beep(500 + (uint16_t)(step % 8) * 60, 60); }



void ExpansionBoradControl(uint8_t command,
    uint16_t p60, uint16_t p62, uint16_t p64, uint16_t p66,
    uint16_t p74, uint16_t p75, uint16_t p76, uint16_t p77)
{
    uint8_t i;
    control_frame_pack[0] = COMM_HEADER_1;
    control_frame_pack[1] = COMM_HEADER_2;
    control_frame_pack[2] = command;
    /* 逐字展开落帧，与《RM电控指南》的参考实现一致：SDCC 对
       "values[] 数组 + 3+i*2 变址" 的写法会取错字节（低字节位置被写成高字节，
       即 10000 发成 0x2727、500 发成 0x0101），这里直接从形参取高/低字节。 */
    control_frame_pack[3] = (uint8_t)((p60 >> 8) & 0xFF);
    control_frame_pack[4] = (uint8_t)(p60 & 0xFF);
    control_frame_pack[5] = (uint8_t)((p62 >> 8) & 0xFF);
    control_frame_pack[6] = (uint8_t)(p62 & 0xFF);
    control_frame_pack[7] = (uint8_t)((p64 >> 8) & 0xFF);
    control_frame_pack[8] = (uint8_t)(p64 & 0xFF);
    control_frame_pack[9] = (uint8_t)((p66 >> 8) & 0xFF);
    control_frame_pack[10] = (uint8_t)(p66 & 0xFF);
    control_frame_pack[11] = (uint8_t)((p74 >> 8) & 0xFF);
    control_frame_pack[12] = (uint8_t)(p74 & 0xFF);
    control_frame_pack[13] = (uint8_t)((p75 >> 8) & 0xFF);
    control_frame_pack[14] = (uint8_t)(p75 & 0xFF);
    control_frame_pack[15] = (uint8_t)((p76 >> 8) & 0xFF);
    control_frame_pack[16] = (uint8_t)(p76 & 0xFF);
    control_frame_pack[17] = (uint8_t)((p77 >> 8) & 0xFF);
    control_frame_pack[18] = (uint8_t)(p77 & 0xFF);
    control_frame_pack[19] = COMM_END_1;
    control_frame_pack[20] = COMM_END_2;
    for (i = 0; i < 21; i++) {
        Uart1TxQuery(control_frame_pack[i]);
    }
}

void ReadControllerInputs(void)
{
    valueOfRoker[0][0] = RcRockerValueRead(ROCKER_LEFT_HORIZONTAL);
    valueOfRoker[0][1] = RcRockerValueRead(ROCKER_LEFT_VERTICAL);
    valueOfRoker[1][0] = RcRockerValueRead(ROCKER_RIGHT_HORIZONTAL);
    valueOfRoker[1][1] = RcRockerValueRead(ROCKER_RIGHT_VERTICAL);
    if (abs(valueOfRoker[0][0]) <= deadBandOfLeft) valueOfRoker[0][0] = 0;
    if (abs(valueOfRoker[0][1]) <= deadBandOfLeft) valueOfRoker[0][1] = 0;
    if (abs(valueOfRoker[1][0]) <= deadBandOfRight) valueOfRoker[1][0] = 0;
    if (abs(valueOfRoker[1][1]) <= deadBandOfRight) valueOfRoker[1][1] = 0;
}

#define FRICTION_START_DUTY 500
#define FRICTION_LEVEL_MAX 100
#define FRICTION_RAMP_STEP 1
#define FRICTION_ACTIVATE_MS 1000
#define FRICTION_LOOP_MS 20
#define FRICTION_ACTIVATE_LOOPS ((FRICTION_ACTIVATE_MS + FRICTION_LOOP_MS - 1) / FRICTION_LOOP_MS)
#define FRICTION_RATE_LOOPS 50
#define FRICTION_MAX_DUTY_P64 700
#define FRICTION_MAX_DUTY_P66 800
uint8_t frictionLevel = 0;
uint16_t frictionTargetDutyP64 = 0;
uint16_t frictionTargetDutyP66 = 0;
uint16_t frictionDutyP64 = 0;
uint16_t frictionDutyP66 = 0;
uint8_t frictionActivateLoops = 0;
uint8_t frictionKeyLast[2] = {0};
int32_t frictionRateAcc[1] = {0};
static uint16_t FrictionDutyOfLevel(uint8_t level, uint16_t maxDuty)
{
    return (uint16_t)(FRICTION_START_DUTY
        + ((uint16_t)level * (uint16_t)(maxDuty - FRICTION_START_DUTY)) / FRICTION_LEVEL_MAX);
}
static void UpdateFriction(void)
{
    if (frictionLevel == 0) frictionActivateLoops = 0;
    frictionTargetDutyP64 = frictionLevel > 0
        ? FrictionDutyOfLevel(frictionLevel, FRICTION_MAX_DUTY_P64) : 0;
    frictionTargetDutyP66 = frictionLevel > 0
        ? FrictionDutyOfLevel(frictionLevel, FRICTION_MAX_DUTY_P66) : 0;
    if (frictionLevel > 0 && frictionDutyP64 == 0
        && frictionTargetDutyP64 >= FRICTION_START_DUTY)
        frictionActivateLoops = FRICTION_ACTIVATE_LOOPS;
    if (frictionActivateLoops > 0) {
        frictionActivateLoops--;
        frictionDutyP64 = FRICTION_START_DUTY;
        frictionDutyP66 = FRICTION_START_DUTY;
    } else {
        if (frictionTargetDutyP64 >= FRICTION_START_DUTY && frictionDutyP64 < FRICTION_START_DUTY)
            frictionDutyP64 = FRICTION_START_DUTY;
        else if (frictionDutyP64 < frictionTargetDutyP64)
            frictionDutyP64 += FRICTION_RAMP_STEP;
        else if (frictionDutyP64 > frictionTargetDutyP64) {
            if (frictionTargetDutyP64 == 0 && frictionDutyP64 <= FRICTION_START_DUTY)
                frictionDutyP64 = 0;
            else
                frictionDutyP64 -= FRICTION_RAMP_STEP;
        }
        if (frictionTargetDutyP66 >= FRICTION_START_DUTY && frictionDutyP66 < FRICTION_START_DUTY)
            frictionDutyP66 = FRICTION_START_DUTY;
        else if (frictionDutyP66 < frictionTargetDutyP66)
            frictionDutyP66 += FRICTION_RAMP_STEP;
        else if (frictionDutyP66 > frictionTargetDutyP66) {
            if (frictionTargetDutyP66 == 0 && frictionDutyP66 <= FRICTION_START_DUTY)
                frictionDutyP66 = 0;
            else
                frictionDutyP66 -= FRICTION_RAMP_STEP;
        }
    }
    dutyOfMotor[2] = frictionDutyP64;
    dutyOfMotor[3] = frictionDutyP66;
}
uint8_t currentMode = 1;
uint8_t lastSwitch = 0;
uint8_t modeKeyLast[4] = {0};
int mainServoDuty[2] = {750, 750};
int32_t servoButtonRemainder[2] = {0};
uint8_t servoButtonKeyLast[2] = {0};
static void ModeSwitchFeedback(uint8_t mode)
{
    Beep(523, 500);
    Ms_Delay(200);
    if (mode >= 1) { Beep(659, 200); if (mode > 1) Ms_Delay(200); }
    if (mode >= 2) { Beep(784, 200); if (mode > 2) Ms_Delay(200); }
    if (mode >= 3) { Beep(1047, 200); if (mode > 3) Ms_Delay(200); }
    if (mode >= 4) Beep(1319, 200);
}

static void PrepareMode(uint8_t mode)
{
    switch (mode) {
        case 1:

            break;
        case 2:
            dutyOfMotor[4] = 0;
            dutyOfMotor[5] = 0;
            dutyOfMotor[6] = 0;
            dutyOfMotor[7] = 0;
            break;
    }
}

uint8_t servoButtonStateMode = 0;
static void SyncServoButtonKeys(uint8_t mode)
{
    switch (mode) {
        case 1:
            servoButtonKeyLast[0] = RcKeyValueRead(KEY_OFFSET_A);
            break;
        case 2:
            servoButtonKeyLast[1] = RcKeyValueRead(KEY_OFFSET_D);
            break;
    }
}

uint8_t frictionStateMode = 0;
static void SyncFrictionKeys(uint8_t mode)
{
    switch (mode) {
        case 1:
            frictionKeyLast[0] = RcKeyValueRead(KEY_OFFSET_C);
            frictionKeyLast[1] = RcKeyValueRead(KEY_OFFSET_D);
            break;
        case 2:
            frictionRateAcc[0] = 0;
            break;
    }
}
static uint8_t servoFeedbackInitialized = 0;
static uint16_t lastServoFeedback[2] = {0};
static void UpdateServoFeedback(void)
{
    uint8_t changed = 0;
    uint16_t feedbackDuty = 0;
    if (servoFeedbackInitialized && dutyOfMotor[0] != lastServoFeedback[0]) { changed = 1; feedbackDuty = dutyOfMotor[0]; }
    lastServoFeedback[0] = dutyOfMotor[0];
    if (servoFeedbackInitialized && dutyOfMotor[1] != lastServoFeedback[1]) { changed = 1; feedbackDuty = dutyOfMotor[1]; }
    lastServoFeedback[1] = dutyOfMotor[1];
    if (!servoFeedbackInitialized) { servoFeedbackInitialized = 1; changed = 0; }
    if (changed) PWM_SET_Frequency(BUZZER_CH, feedbackDuty, 5000);
    else if (frictionActivateLoops == 0 && (frictionDutyP64 != frictionTargetDutyP64 || frictionDutyP66 != frictionTargetDutyP66)) PWM_SET_Frequency(BUZZER_CH, frictionDutyP64, 5000);
    else PWM_SET_Frequency(BUZZER_CH, 500, 0);
}



void CalculateChassis(void)
{
    int speed = maxSpeed;
    int baseSpeed;
    int turnSpeed;
    baseSpeed = (int)(((int32_t)-valueOfRoker[0][1] * (int32_t)speed) / 2047L);
    turnSpeed = (int)(((int32_t)-valueOfRoker[0][0] * (int32_t)speed) / 2047L);
    dutyOfMotor[4] = baseSpeed - turnSpeed;
    dutyOfMotor[5] = baseSpeed - turnSpeed;
    dutyOfMotor[6] = baseSpeed + turnSpeed;
    dutyOfMotor[7] = baseSpeed + turnSpeed;
}

void RunMode1(void)
{
    CalculateChassis();
    if (RcKeyValueRead(KEY_OFFSET_A) && !servoButtonKeyLast[0]) {
        servoButtonRemainder[0] += 500000L;
        dutyOfMotor[0] += (int)(servoButtonRemainder[0] / 18000L);
        servoButtonRemainder[0] %= 18000L;
    }
    servoButtonKeyLast[0] = RcKeyValueRead(KEY_OFFSET_A);
    if (dutyOfMotor[0] < 250) { dutyOfMotor[0] = 250; servoButtonRemainder[0] = 0; } else if (dutyOfMotor[0] > 1250) { dutyOfMotor[0] = 1250; servoButtonRemainder[0] = 0; }
    if (RcKeyValueRead(KEY_OFFSET_B)) {
        servoButtonRemainder[1] += 300000L;
        dutyOfMotor[1] += (int)(servoButtonRemainder[1] / 18000L);
        servoButtonRemainder[1] %= 18000L;
    }
    if (dutyOfMotor[1] < 250) { dutyOfMotor[1] = 250; servoButtonRemainder[1] = 0; } else if (dutyOfMotor[1] > 1250) { dutyOfMotor[1] = 1250; servoButtonRemainder[1] = 0; }
    if (RcKeyValueRead(KEY_OFFSET_C) && !frictionKeyLast[0]) frictionLevel = frictionLevel > 0 ? 0 : 100;
    frictionKeyLast[0] = RcKeyValueRead(KEY_OFFSET_C);
    if (RcKeyValueRead(KEY_OFFSET_D) && !frictionKeyLast[1]) {
        if (frictionLevel - 10 > FRICTION_LEVEL_MAX) frictionLevel = FRICTION_LEVEL_MAX;
        else if (frictionLevel - 10 < 0) frictionLevel = 0;
        else frictionLevel = frictionLevel - 10;
    }
    frictionKeyLast[1] = RcKeyValueRead(KEY_OFFSET_D);
}

void RunMode2(void)
{
    dutyOfMotor[0] += (int)((float)valueOfRoker[0][0] * 20 * 1000.0f / 180.0f / 2047.0f);
    if (dutyOfMotor[0] < 250) dutyOfMotor[0] = 250; else if (dutyOfMotor[0] > 1250) dutyOfMotor[0] = 1250;
    frictionRateAcc[0] += (int32_t)valueOfRoker[1][1] * 50;
    while (frictionRateAcc[0] >= 2047L * FRICTION_RATE_LOOPS) {
        frictionRateAcc[0] -= 2047L * FRICTION_RATE_LOOPS;
        if (frictionLevel < FRICTION_LEVEL_MAX) frictionLevel++;
    }
    while (frictionRateAcc[0] <= -2047L * FRICTION_RATE_LOOPS) {
        frictionRateAcc[0] += 2047L * FRICTION_RATE_LOOPS;
        if (frictionLevel > 0) frictionLevel--;
    }
    if (frictionLevel == 0 && frictionRateAcc[0] < 0) frictionRateAcc[0] = 0;
    else if (frictionLevel == FRICTION_LEVEL_MAX && frictionRateAcc[0] > 0) frictionRateAcc[0] = 0;
    if (RcKeyValueRead(KEY_OFFSET_D) && !servoButtonKeyLast[1]) dutyOfMotor[1] = 500;
    servoButtonKeyLast[1] = RcKeyValueRead(KEY_OFFSET_D);
}

void All_Init(void)
{
    StepBegin(0);
    Board_Init();
    StepDone(0);
    StepBegin(1);
    UART_Init(UART_1, UART1_RX_P30, UART1_TX_P31, 230400, TIM1);
    StepDone(1);
    GPIO_Init(LED_PORT, (GPIO_Pin_enum)(LED1_PIN | LED2_PIN | LED3_PIN), GPIO_OUT_PP);
    PWM_Init(BUZZER_CH, 500, 0);
    StepBegin(3);
    EA = 0;
    remoteControlInitWithTimeout();
    P2INTE &= ~GPIO_Pin_6;
    EA = 1;
    StepDone(3);
    ExpansionBoradControl(Init_Order, 50, 50, 50, 50, 10000, 10000, 10000, 10000);
    Ms_Delay(EXPANSION_FRAME_GAP_MS);
    dutyOfMotor[0] = 750;
    dutyOfMotor[1] = 750;
    PrepareMode(1);
    Beep(523, 120);
    Beep(659, 120);
    Beep(784, 120);
    Beep(1047, 240);
}

void main(void)
{
    All_Init();
    while (1) {
        nrf_handler(); // 轮询 NRF 接收（P2.6 中断已关）
        ReadControllerInputs();
        if (RcKeyValueRead(KEY_OFFSET_1) && !lastSwitch) { currentMode++; if (currentMode > 2) currentMode = 1; PrepareMode(currentMode); ModeSwitchFeedback(currentMode); }
        lastSwitch = RcKeyValueRead(KEY_OFFSET_1);
        if (servoButtonStateMode != currentMode) {
            SyncServoButtonKeys(currentMode);
            servoButtonStateMode = currentMode;
        }
        if (frictionStateMode != currentMode) {
            SyncFrictionKeys(currentMode);
            frictionStateMode = currentMode;
        }
        switch (currentMode) {
        case 1: RunMode1(); break;
        case 2: RunMode2(); break;
        }
        UpdateFriction();
        ExpansionBoradControl(Dir_Change_Order, 1,1,dutyOfMotor[2]>=0,dutyOfMotor[3]>=0,dutyOfMotor[4]>=0,dutyOfMotor[5]>=0,dutyOfMotor[6]>=0,dutyOfMotor[7]>=0);
        Ms_Delay(EXPANSION_FRAME_GAP_MS);
        ExpansionBoradControl(Duty_Change_Order, abs(dutyOfMotor[0]),abs(dutyOfMotor[1]),abs(dutyOfMotor[2]),abs(dutyOfMotor[3]),abs(dutyOfMotor[4]),abs(dutyOfMotor[5]),abs(dutyOfMotor[6]),abs(dutyOfMotor[7]));
        Ms_Delay(EXPANSION_FRAME_GAP_MS);


        UpdateServoFeedback();
        Ms_Delay(10);
    }
}

