    remoteControlInitWithTimeout();
    P2INTE &= ~GPIO_Pin_6;
    EA = 1;
    StepDone(3);
    ExpansionBoradControl(Init_Order, 50, 50, 50, 50, 10000, 10000, 10000, 10000);
    Ms_Delay(EXPANSION_FRAME_GAP_MS);
    dutyOfMotor[0] = 750;
    dutyOfMotor[1] = 750;
