    else if (frictionActivateLoops == 0 && (frictionDutyP64 != frictionTargetDutyP64 || frictionDutyP66 != frictionTargetDutyP66)) PWM_SET_Frequency(BUZZER_CH, frictionDutyP64, 5000);
