        servoButtonRemainder[0] += 500000L;
        dutyOfMotor[0] += (int)(servoButtonRemainder[0] / 18000L);
        servoButtonRemainder[0] %= 18000L;
    }
    servoButtonKeyLast[0] = RcKeyValueRead(KEY_OFFSET_A);
    if (dutyOfMotor[0] < 250) { dutyOfMotor[0] = 250; servoButtonRemainder[0] = 0; } else if (dutyOfMotor[0] > 1250) { dutyOfMotor[0] = 1250; servoButtonRemainder[0] = 0; }
    if (RcKeyValueRead(KEY_OFFSET_B)) {
        servoButtonRemainder[1] += 300000L;
        dutyOfMotor[1] += (int)(servoButtonRemainder[1] / 18000L);
        servoButtonRemainder[1] %= 18000L;
    }
    if (dutyOfMotor[1] < 250) { dutyOfMotor[1] = 250; servoButtonRemainder[1] = 0; } else if (dutyOfMotor[1] > 1250) { dutyOfMotor[1] = 1250; servoButtonRemainder[1] = 0; }
    if (RcKeyValueRead(KEY_OFFSET_C) && !frictionKeyLast[0]) frictionLevel = frictionLevel > 0 ? 0 : 100;
    frictionKeyLast[0] = RcKeyValueRead(KEY_OFFSET_C);
    if (RcKeyValueRead(KEY_OFFSET_D) && !frictionKeyLast[1]) {
        if (frictionLevel - 10 > FRICTION_LEVEL_MAX) frictionLevel = FRICTION_LEVEL_MAX;
