}

void RunMode2(void)
{
    dutyOfMotor[0] += (int)((float)valueOfRoker[0][0] * 20 * 1000.0f / 180.0f / 2047.0f);
    if (dutyOfMotor[0] < 250) dutyOfMotor[0] = 250; else if (dutyOfMotor[0] > 1250) dutyOfMotor[0] = 1250;
    frictionRateAcc[0] += (int32_t)valueOfRoker[1][1] * 50;
    while (frictionRateAcc[0] >= 2047L * FRICTION_RATE_LOOPS) {
        frictionRateAcc[0] -= 2047L * FRICTION_RATE_LOOPS;
        if (frictionLevel < FRICTION_LEVEL_MAX) frictionLevel++;
    }
    while (frictionRateAcc[0] <= -2047L * FRICTION_RATE_LOOPS) {
        frictionRateAcc[0] += 2047L * FRICTION_RATE_LOOPS;
        if (frictionLevel > 0) frictionLevel--;
    }
    if (frictionLevel == 0 && frictionRateAcc[0] < 0) frictionRateAcc[0] = 0;
    else if (frictionLevel == FRICTION_LEVEL_MAX && frictionRateAcc[0] > 0) frictionRateAcc[0] = 0;
