        ExpansionBoradControl(Dir_Change_Order, dutyOfMotor[0]>=0,dutyOfMotor[1]>=0,1,1,dutyOfMotor[4]>=0,dutyOfMotor[5]>=0,dutyOfMotor[6]>=0,dutyOfMotor[7]>=0);
        Ms_Delay(EXPANSION_FRAME_GAP_MS);
        ExpansionBoradControl(Duty_Change_Order, abs(dutyOfMotor[0]),abs(dutyOfMotor[1]),frictionDutyP64,frictionDutyP66,abs(dutyOfMotor[4]),abs(dutyOfMotor[5]),abs(dutyOfMotor[6]),abs(dutyOfMotor[7]));
        Ms_Delay(EXPANSION_FRAME_GAP_MS);
